#### B. Verification Unit Tests: `ui/src/lib/terminalHostManager.output.test.ts` (or `terminalHostManager.test.ts`)

```typescript
import { fitTerminalInstance } from "./terminalInstanceFactory";
import { terminalScrolledToBottom } from "./terminalHostManagerTestHelper";

it("realigns viewport to bottom after fit when terminal is replayed / at bottom", async () => {
  const session = createSession("sess-realign", "backend-realign");
  const unreg = terminalHostManager.registerVisible("sess-realign");
  const instance = await terminalHostManager.getOrCreate(session, true);

  // Simulate replayed output at bottom
  instance.terminal.buffer.active.baseY = 40;
  instance.terminal.buffer.active.viewportY = 40;
  terminalScrolledToBottom.mockClear();

  fitTerminalInstance(instance.terminal, instance.fitAddon);

  expect(instance.fitAddon.fit).toHaveBeenCalledTimes(1);
  expect(terminalScrolledToBottom).toHaveBeenCalledTimes(1);
  expect(instance.terminal.buffer.active.viewportY).toBe(40);

  unreg();
  terminalHostManager.destroy("sess-realign");
});

it("does NOT scroll to bottom on fit when user has deliberately scrolled up into scrollback", async () => {
  const session = createSession("sess-scrollback", "backend-scrollback");
  const unreg = terminalHostManager.registerVisible("sess-scrollback");
  const instance = await terminalHostManager.getOrCreate(session, true);

  // User scrolled up: baseY is 50, viewportY is 10
  instance.terminal.buffer.active.baseY = 50;
  instance.terminal.buffer.active.viewportY = 10;
  terminalScrolledToBottom.mockClear();

  fitTerminalInstance(instance.terminal, instance.fitAddon);

  expect(instance.fitAddon.fit).toHaveBeenCalledTimes(1);
  expect(terminalScrolledToBottom).not.toHaveBeenCalled();
  expect(instance.terminal.buffer.active.viewportY).toBe(10);

  unreg();
  terminalHostManager.destroy("sess-scrollback");
});

it("does NOT scroll to bottom on normal live output flush while scrolled up", async () => {
  const session = createSession("sess-live-scroll", "backend-live-scroll");
  const unreg = terminalHostManager.registerVisible("sess-live-scroll");
  const instance = await terminalHostManager.getOrCreate(session, true);

  instance.terminal.buffer.active.baseY = 50;
  instance.terminal.buffer.active.viewportY = 10;
  terminalScrolledToBottom.mockClear();

  mocks.emitSessionOutput("backend-live-scroll", "new live output chunk");
  flushAnimationFrames();

  expect(mocks.terminalWrites).toContain("new live output chunk");
  expect(terminalScrolledToBottom).not.toHaveBeenCalled();

  unreg();
  terminalHostManager.destroy("sess-live-scroll");
});
```

---

### 5. Recommendation

Apply the `fitTerminalInstance` helper across the 3 call sites (`terminalInstanceFactory.ts`, `TerminalPane.tsx`, `terminalHostManager.ts`) while keeping `terminalOutputScheduler.ts` untouched. This achieves viewport realignment on reactivation and fitting with zero regression to LRU caching or user scrollback behavior.
